<script setup lang="ts">
import {ref} from "vue";import {onShow,onPullDownRefresh} from "@dcloudio/uni-app";import {request} from "../../api";
const entries=ref<any[]>([]);async function load(){try{entries.value=await request<any[]>("/api/v1/entries")}catch(e:any){if(e.message.includes("未登录")||e.message.includes("过期"))uni.redirectTo({url:"/pages/login/login"});else if(e.message.includes("空间"))uni.redirectTo({url:"/pages/space/space"})}finally{uni.stopPullDownRefresh()}}onShow(load);onPullDownRefresh(load);
</script>
<template><view class="page"><view class="hero"><text class="title">我们的时光</text><text class="hint">下拉刷新，即可看到另一半的新日记</text></view><view v-if="!entries.length" class="empty">还没有日记，去写下第一篇吧。</view><view v-for="e in entries" :key="e.id" class="card" @click="uni.navigateTo({url:'/pages/detail/detail?id='+e.id})"><view><text class="date">{{e.happened_on}}</text><text class="mood">{{e.mood}}</text></view><text class="entry-title">{{e.title||'无题'}}</text><text class="body">{{e.body}}</text><text class="author">{{e.author_nickname}} · {{e.visibility==='private'?'仅自己':'共享'}}</text></view></view></template>
<style scoped>.page{padding:34rpx}.hero{padding:26rpx 8rpx}.title{display:block;font-size:48rpx;font-weight:700}.hint,.date,.author{color:#9a7479;font-size:25rpx}.card,.empty{background:white;padding:30rpx;border-radius:24rpx;margin:22rpx 0;box-shadow:0 10rpx 30rpx #7c34400d}.mood{float:right;background:#fff0ee;color:#c45c6a;padding:6rpx 14rpx;border-radius:999rpx}.entry-title{display:block;font-size:34rpx;font-weight:650;margin:18rpx 0 8rpx}.body{display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;margin-bottom:18rpx}.author{display:block}</style>

